patch:
diff --git a/sql/sql_parse.cc b/sql/sql_parse.cc
index d27e36bc9b11..cdfb00ad4ee7 100644
--- a/sql/sql_parse.cc
+++ b/sql/sql_parse.cc
@@ -3894,6 +3894,10 @@ int mysql_execute_command(THD *thd, bool first_level) {
         }
       }
       if (first_table) {
+        if (lex->dynamic_privileges.elements > 0) {
+          my_error(ER_ILLEGAL_PRIVILEGE_LEVEL, MYF(0), all_tables->table_name);
+          goto error;
+        }
         if (lex->type == TYPE_ENUM_PROCEDURE ||
             lex->type == TYPE_ENUM_FUNCTION) {
           uint grants = lex->all_privileges
@@ -3911,11 +3915,6 @@ int mysql_execute_command(THD *thd, bool first_level) {
           if (check_grant(thd, (lex->grant | lex->grant_tot_col | GRANT_ACL),
                           all_tables, false, UINT_MAX, false))
             goto error;
-          if (lex->dynamic_privileges.elements > 0) {
-            my_error(ER_ILLEGAL_PRIVILEGE_LEVEL, MYF(0),
-                     all_tables->table_name);
-            goto error;
-          }
           /* Conditionally writes to binlog */
           res =
               mysql_table_grant(thd, all_tables, lex->users_list, lex->columns,

test_patch:
diff --git a/mysql-test/r/grant_dynamic_bugs.result b/mysql-test/r/grant_dynamic_bugs.result
new file mode 100644
index 000000000000..f2c90778065f
--- /dev/null
+++ b/mysql-test/r/grant_dynamic_bugs.result
@@ -0,0 +1,12 @@
+#
+# Bug #30628160: DYNAMIC PRIVILEGES CAN BE GRANTED AT PROCEDURE/FUNCTION LEVEL
+#
+CREATE SCHEMA B30628160;
+CREATE PROCEDURE B30628160.p1() SELECT 1;
+CREATE USER B30628160@localhost;
+# The test: must fail.
+GRANT xyzzy ON PROCEDURE B30628160.p1 TO B30628160@localhost;
+ERROR HY000: Illegal privilege level specified for p1
+DROP USER B30628160@localhost;
+DROP SCHEMA B30628160;
+# End of 8.0 tests
diff --git a/mysql-test/t/grant_dynamic_bugs.test b/mysql-test/t/grant_dynamic_bugs.test
new file mode 100644
index 000000000000..74b28163fb64
--- /dev/null
+++ b/mysql-test/t/grant_dynamic_bugs.test
@@ -0,0 +1,15 @@
+--echo #
+--echo # Bug #30628160: DYNAMIC PRIVILEGES CAN BE GRANTED AT PROCEDURE/FUNCTION LEVEL
+--echo #
+
